import{_ as s}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as i}from"./chunks/ON.DXVlsWbj.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as o}from"./chunks/DIS.DdpTdGGD.js";import{_ as n,o as a,c as r,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"NFC Scan Features","description":"","frontmatter":{},"headers":[],"relativePath":"use/NFC.md","filePath":"use/NFC.md"}'),l={name:"use/NFC.md"};function d(c,t,m,h,u,b){return a(),r("div",null,[...t[0]||(t[0]=[p('<p>This menu will only appear if a <a href="./../install/datasource.html#libre">Libre hardware data source</a> is selected.</p><p>If your phone has an <strong>ISO 15693 compatible NFC chip</strong>, you can use the xDrip NFC feature with Libre 1/14 days/Pro and 2/2+ (EU).</p><p>Remember to first enable the NFC feature in Android settings.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_nfc_grey600_48dp.png" style="width:5%;"> NFC Scan features</p></div><div class="admonition xdripitem"><p class="admonition-title">Use NFC Feature <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Allow sensors to be scanned when app is open. Historic data will be back-filled. Highly experimental! Beware this can maybe break a sensor. Test phone compatibility with an almost expired sensor first. You have been warned!</p></div><p>You can display sensor age at the bottom of the main graph (xDrip master).</p><div class="admonition xdripitem"><p class="admonition-title">Sensor Age or Expiry <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Show the sensor age on the main screen</p></div><p>In order to automatically open xDrip upon NFC sensor detection you should <strong>enable</strong> Scan when not in xDrip (recommended). If several apps can scan NFC devices, you will be asked to select the one to use at each scan.</p><div class="admonition xdripitem"><p class="admonition-title">Scan when not in xDrip <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> NFC scanning will also work from your app launcher screen.</p></div><p>You can decide how xDrip will inform you that the scan completed. Vibration and sound are helpful during (long) NFC scans, you should <strong>enable</strong> both.</p><p>When scanning remember that you need to keep the phone in the NFC antenna spot for some seconds to allow a correct scan. Consult your phone manufacturer documentation to find where it is located.</p><div class="admonition xdripitem"><p class="admonition-title">Vibrate to indicate scanning status <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Beep when scanning within xDrip app <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p>Only visible with Engineering Mode enabled.</p></div><p>Faster scan is <strong>enabled</strong> by default. If you have trouble scanning sensors, try disabling it.</p><div class="admonition xdripitem"><p class="admonition-title">Use faster multi-block reading method <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>If you have trouble with your phone NFC, try to <strong>enable</strong> Any tag method.</p><div class="admonition xdripitem"><p class="admonition-title">Use any-tag optimized reading method <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><h2 id="starting-bluetooth-connection-with-libre2-sensors" tabindex="-1">Starting Bluetooth connection with Libre2 sensors <a class="header-anchor" href="#starting-bluetooth-connection-with-libre2-sensors" aria-label="Permalink to &quot;Starting Bluetooth connection with Libre2 sensors&quot;">​</a></h2><p>This feature allows xDrip to take ownership of the sensor Bluetooth connection. On most phones this is not compatible with the vendor app (only one app can connect to the same sensor). Some users report the possibility to connect both the vendor app and xDrip at the same time, but this is not guaranteed: uninstall the vendor app if you want xDrip to be connected to the sensor.</p><div class="admonition xdripitem"><p class="admonition-title">Starting Bluetooth connection with Libre2 sensors</p><p> Connect to Libre2 sensors after scanning them. This will stop Libre reader and Librelink from receiving alerts</p></div><p>This selection will pop up when you scan a new Libre 2 sensor only if you selected Ask me every time.</p><p>Be aware that Always connect to Libre2 sensors will most probably disconnect any other app or device connected to the sensor. If xDrip successfully pairs, there will be no possible connection recovery from the other device/app.</p><div class="admonition xdripitem"><p class="admonition-title">Starting Bluetooth connection with Libre2 sensors</p><p> Always connect to Libre2 sensors<span style="float:right;">○ </span>   <br>  Ask me every time<span style="float:right;">● </span><br>  Never connect to Libre2 sensors<span style="float:right;">○ </span></p></div><h2 id="smooth-libre-3-data-when-using-xxx-method" tabindex="-1">Smooth libre 3 data when using xxx method <a class="header-anchor" href="#smooth-libre-3-data-when-using-xxx-method" aria-label="Permalink to &quot;Smooth libre 3 data when using xxx method&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Note</p><p>Smoothing will apply to any external data source app using the <code>Libre2 (patched app)</code> data source.</p></div><p>The original implementation included a 25-minute smoothing algorithm to remove noise and make DIY closed looping safer with Libre sensors. You can change the smoothing period to 10, 15 or 25 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Smooth Libre 3 data when using xxx method</p><p> Number of minutes to take in consideration when using librex data</p></div><p>Smoothing adds a delay in xDrip BG from raw data. The delay is about half the smoothing period. Set the delay according to the sensor behavior for your safety. If you don&#39;t use a DIY closed loop system with xDrip providing glucose values, set it to 10 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Smooth libre 3 data when using xxx method</p><p> 10 minutes<span style="float:right;">○ </span>   <br>  15 minutes<span style="float:right;">○ </span><br>  25 minutes &gt;<span style="float:right;">● </span></p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',31)])])}const _=n(l,[["render",d]]);export{v as __pageData,_ as default};
